#![allow(clippy::unwrap_used, clippy::expect_used)]
//! Every fixture sprite, every frame, against Aseprite's own flattened PNG
//! (generated by tools/fixtures/render_oracle.sh). Pixel-exact.
use std::path::{Path, PathBuf};

use rp_core::RgbaImage;
use rp_render::{RenderOptions, render_frame};

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

/// Decodes a PNG to RGBA8, expanding indexed and greyscale on the way.
fn decode_png(path: &Path) -> RgbaImage {
    let bytes = std::fs::read(path).unwrap();
    let mut decoder = png::Decoder::new(std::io::Cursor::new(bytes));
    decoder.set_transformations(
        png::Transformations::EXPAND | png::Transformations::ALPHA | png::Transformations::STRIP_16,
    );
    let mut reader = decoder.read_info().unwrap();
    let mut buf = vec![0; reader.output_buffer_size().unwrap()];
    let info = reader.next_frame(&mut buf).unwrap();
    let samples = info.color_type.samples();
    let mut px = Vec::new();
    for s in buf[..info.buffer_size()].chunks_exact(samples) {
        match s {
            [r, g, b, a] => px.extend_from_slice(&[*r, *g, *b, *a]),
            [r, g, b] => px.extend_from_slice(&[*r, *g, *b, 255]),
            [v, a] => px.extend_from_slice(&[*v, *v, *v, *a]),
            [v] => px.extend_from_slice(&[*v, *v, *v, 255]),
            _ => unreachable!(),
        }
    }
    RgbaImage::from_raw(info.width, info.height, px).unwrap()
}

/// None if equal under the oracle rule (both alpha 0, or all four channels equal),
/// else (mismatch count, first mismatch description).
fn compare(expected: &RgbaImage, actual: &RgbaImage) -> Option<(usize, String)> {
    if (expected.width(), expected.height()) != (actual.width(), actual.height()) {
        return Some((
            usize::MAX,
            format!(
                "size: expected {}x{}, got {}x{}",
                expected.width(),
                expected.height(),
                actual.width(),
                actual.height()
            ),
        ));
    }
    let mut count = 0;
    let mut first = String::new();
    for y in 0..expected.height() {
        for x in 0..expected.width() {
            let e = expected.get(x, y).unwrap();
            let a = actual.get(x, y).unwrap();
            let same = (e[3] == 0 && a[3] == 0) || e == a;
            if !same {
                if count == 0 {
                    first = format!("({x},{y}) expected {e:?} got {a:?}");
                }
                count += 1;
            }
        }
    }
    (count > 0).then_some((count, first))
}

#[test]
fn every_fixture_matches_aseprite() {
    let mut entries: Vec<PathBuf> = std::fs::read_dir(fixtures())
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.extension().is_some_and(|x| x == "aseprite"))
        .collect();
    entries.sort();
    assert!(
        entries.len() >= 50,
        "oracle missing: run tools/fixtures/render_oracle.sh"
    );

    let mut failures = Vec::new();
    let mut checked = 0;
    for path in &entries {
        let name = path.file_stem().unwrap().to_string_lossy().to_string();
        let sprite = rp_io::read(&std::fs::read(path).unwrap()).unwrap();
        for frame in 0..sprite.frames.len() as u32 {
            let png = fixtures().join(format!("{name}_{frame}.png"));
            let expected = decode_png(&png);
            match render_frame(&sprite, frame, &RenderOptions::default()) {
                Err(e) => failures.push(format!("{name} frame {frame}: error {e}")),
                Ok(actual) => {
                    if let Some((n, first)) = compare(&expected, &actual) {
                        failures.push(format!(
                            "{name} frame {frame}: {n} pixels differ, first {first}"
                        ));
                    }
                }
            }
            checked += 1;
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} renders differ:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
